import os
import uuid
import time
from typing import List, Optional, Dict, Any

import requests
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field

from cerebras.cloud.sdk import Cerebras
from parallel import Parallel
from parallel.types import TaskSpecParam, TextSchemaParam


class QueryRequest(BaseModel):
    query: str = Field(..., min_length=1)
    mode: str = Field("search", regex="^(search|research)$")
    user_id: Optional[str] = None
    maximum_tokens: int = 2048


class Citation(BaseModel):
    id: int
    title: Optional[str] = None
    url: Optional[str] = None
    source: Optional[str] = None


class QueryResponse(BaseModel):
    answer: str
    citations: List[Citation]
    plan: List[str]
    debug: Dict[str, Any]


class ExaClient:
    def __init__(self) -> None:
        self.api_key = os.getenv("EXA_API_KEY")
        if not self.api_key:
            raise RuntimeError("EXA_API_KEY environment variable is required")
        self.base_url = os.getenv("EXA_SEARCH_URL", "https://api.exa.ai/search")

    def search_deep(
        self,
        query: str,
        maximum_results: int = 100,
        search_type: str = "deep",
        category: Optional[str] = None,
        country_code: Optional[str] = None,
        include_domains: Optional[List[str]] = None,
        exclude_domains: Optional[List[str]] = None,
        include_context: bool = True,
        safe: bool = True,
    ) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "query": query,
            "numResults": maximum_results,
            "type": search_type,
        }
        if category:
            payload["category"] = category
        if country_code:
            payload["country"] = country_code
        if include_domains:
            payload["includeDomains"] = include_domains
        if exclude_domains:
            payload["excludeDomains"] = exclude_domains
        if include_context:
            payload["contents"] = {"text": True}
        if safe:
            payload["moderate"] = True
        headers = {
            "x-api-key": self.api_key,
            "Content-Type": "application/json",
        }
        response = requests.post(self.base_url, json=payload, headers=headers, timeout=60)
        if response.status_code != 200:
            raise HTTPException(
                status_code=502,
                detail=f"Exa search error {response.status_code}: {response.text}",
            )
        return response.json()

    def filter_strict_matches(
        self,
        query: str,
        raw_results: Dict[str, Any],
    ) -> List[Dict[str, Any]]:
        results = raw_results.get("results", [])
        if not results:
            return []
        normalized_query = query.strip().lower()
        if len(normalized_query) < 40 and " " not in normalized_query:
            return results
        strict_results: List[Dict[str, Any]] = []
        for item in results:
            title = (item.get("title") or "").lower()
            text = (item.get("summary") or item.get("text") or "").lower()
            combined = title + " " + text
            if all(part in combined for part in normalized_query.split()):
                strict_results.append(item)
        if strict_results:
            return strict_results
        return results


class ParallelResearchClient:
    def __init__(self) -> None:
        api_key = os.getenv("PARALLEL_API_KEY")
        if not api_key:
            raise RuntimeError("PARALLEL_API_KEY environment variable is required")
        self.client = Parallel(api_key=api_key)
        self.processor = os.getenv("PARALLEL_PROCESSOR", "ultra8x")

    def deep_research_markdown(
        self,
        query: str,
        timeout_seconds: int = 3600,
    ) -> Dict[str, Any]:
        task_run = self.client.task_run.create(
            input=query,
            processor=self.processor,
            task_spec=TaskSpecParam(
                output_schema=TextSchemaParam(
                    description="High quality, well structured markdown research report with inline citations."
                )
            ),
        )
        run_result = self.client.task_run.result(
            task_run.run_id,
            api_timeout=timeout_seconds,
        )
        return {
            "run_id": task_run.run_id,
            "raw_output": run_result.output,
        }


class SupermemoryClient:
    def __init__(self) -> None:
        api_key = os.getenv("SUPERMEMORY_API_KEY")
        if not api_key:
            raise RuntimeError("SUPERMEMORY_API_KEY environment variable is required")
        self.api_key = api_key
        self.base_url = os.getenv(
            "SUPERMEMORY_DOCUMENTS_URL",
            "https://api.supermemory.ai/v3/documents",
        )

    def add_document(
        self,
        content: str,
        source: Optional[str] = None,
        document_type: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "content": content,
        }
        if source:
            payload["source"] = source
        if document_type:
            payload["type"] = document_type
        if metadata:
            payload["metadata"] = metadata
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        response = requests.post(
            self.base_url,
            json=payload,
            headers=headers,
            timeout=30,
        )
        if response.status_code not in (200, 201):
            raise HTTPException(
                status_code=502,
                detail=f"Supermemory error {response.status_code}: {response.text}",
            )
        return response.json()


class GrokClient:
    def __init__(self) -> None:
        self.api_key = os.getenv("XAI_API_KEY")
        self.base_url = os.getenv("XAI_API_BASE_URL", "https://api.x.ai/v1/chat/completions")

    def chat(
        self,
        system_prompt: str,
        user_prompt: str,
        model: str = "grok-4.1-fast",
        maximum_tokens: int = 2048,
        temperature: float = 0.2,
    ) -> str:
        if not self.api_key:
            raise RuntimeError("XAI_API_KEY environment variable is required for Grok usage")
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "max_tokens": maximum_tokens,
            "temperature": temperature,
        }
        response = requests.post(
            self.base_url,
            headers=headers,
            json=payload,
            timeout=120,
        )
        if response.status_code != 200:
            raise HTTPException(
                status_code=502,
                detail=f"Grok API error {response.status_code}: {response.text}",
            )
        data = response.json()
        choices = data.get("choices") or []
        if not choices:
            return ""
        content = choices[0].get("message", {}).get("content", "")
        return content or ""


