class CerebrasLLMOrchestrator:
    def __init__(
        self,
        exa_client: ExaClient,
        parallel_client: ParallelResearchClient,
        supermemory_client: SupermemoryClient,
    ) -> None:
        api_key = os.getenv("CEREBRAS_API_KEY")
        if not api_key:
            raise RuntimeError("CEREBRAS_API_KEY environment variable is required")
        self.client = Cerebras(api_key=api_key)
        self.exa_client = exa_client
        self.parallel_client = parallel_client
        self.supermemory_client = supermemory_client

    def _stream_to_text(self, stream) -> str:
        parts: List[str] = []
        for chunk in stream:
            delta = chunk.choices[0].delta
            content = getattr(delta, "content", None)
            if content:
                parts.append(content)
        return "".join(parts)

    def plan_with_qwen(self, query: str) -> List[str]:
        stream = self.client.chat.completions.create(
            messages=[
                {
                    "role": "system",
                    "content": "Te egy webes kutatási tervező vagy. Készíts lépésről lépésre keresési tervet egy AI keresőmotor számára. Rövid, számozott lépéseket írj.",
                },
                {
                    "role": "user",
                    "content": query,
                },
            ],
            model="qwen-3-235b-a22b-instruct-2507",
            stream=True,
            max_completion_tokens=1024,
            temperature=0.3,
            top_p=0.8,
        )
        text = self._stream_to_text(stream)
        steps: List[str] = []
        for line in text.splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            if stripped[0].isdigit():
                parts = stripped.split(".", 1)
                if len(parts) == 2:
                    step_text = parts[1].strip()
                else:
                    step_text = stripped
                if step_text:
                    steps.append(step_text)
        if not steps:
            steps.append("A kérdés általános megértése és kulcsfogalmak azonosítása.")
            steps.append("Kulcskifejezésekre irányuló webes keresés futtatása.")
            steps.append("Eredmények összefoglalása, ellentmondások keresése, válasz generálása.")
        return steps

    def answer_with_gpt_oss(
        self,
        query: str,
        context_blocks: List[str],
        maximum_tokens: int,
    ) -> str:
        context_text = ""
        for index, block in enumerate(context_blocks, start=1):
            context_text += f"Forrás [{index}]:\n{block}\n\n"
        system_prompt = (
            "Te egy megbízható, forrásokra támaszkodó AI keresőmotor vagy. "
            "Csak az alább megadott forrásokból dolgozol, nem találsz ki új információkat. "
            "Minden fontos állítás végére tegyél szögletes zárójelben hivatkozást a forrás sorszámával, például [1] vagy [2]."
        )
        user_prompt = (
            f"Kérdés:\n{query}\n\n"
            f"Elérhető források:\n{context_text}\n\n"
            "Feladat: Adj tömör, logikusan felépített választ magyarul, csak a forrásokra támaszkodva. "
            "Ha valamire nincs elegendő információ, ezt is írd ki külön."
        )
        stream = self.client.chat.completions.create(
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            model="gpt-oss-120b",
            stream=True,
            max_completion_tokens=maximum_tokens,
            temperature=0.07,
            top_p=1,
            reasoning_effort="low",
        )
        return self._stream_to_text(stream)

    def answer_with_zai_glm(
        self,
        query: str,
        context_blocks: List[str],
        maximum_tokens: int,
    ) -> str:
        context_text = ""
        for index, block in enumerate(context_blocks, start=1):
            context_text += f"Forrás [{index}]:\n{block}\n\n"
        system_prompt = (
            "Te egy megbízható, forrásokra támaszkodó AI keresőmotor vagy. "
            "Csak az alább megadott forrásokból dolgozol, nem találsz ki új információkat. "
            "Minden fontos állítás végére tegyél szögletes zárójelben hivatkozást a forrás sorszámával, például [1] vagy [2]."
        )
        user_prompt = (
            f"Kérdés:\n{query}\n\n"
            f"Elérhető források:\n{context_text}\n\n"
            "Feladat: Adj tömör, logikusan felépített választ magyarul, csak a forrásokra támaszkodva. "
            "Ha valamire nincs elegendő információ, ezt is írd ki külön."
        )
        stream = self.client.chat.completions.create(
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            model="zai-glm-4.6",
            stream=True,
            max_completion_tokens=maximum_tokens,
            temperature=0.97,
            top_p=0.95,
        )
        return self._stream_to_text(stream)

    def handle_search(
        self,
        request: QueryRequest,
    ) -> QueryResponse:
        plan_steps = self.plan_with_qwen(request.query)
        raw_results = self.exa_client.search_deep(
            query=request.query,
            maximum_results=100,
            search_type="deep",
        )
        filtered_results = self.exa_client.filter_strict_matches(
            query=request.query,
            raw_results=raw_results,
        )
        context_blocks: List[str] = []
        citations: List[Citation] = []
        for index, item in enumerate(filtered_results, start=1):
            title = item.get("title") or ""
            url = item.get("url") or ""
            summary = item.get("summary") or item.get("text") or ""
            snippet = summary[:2000]
            block = f"Cím: {title}\nURL: {url}\nRészlet: {snippet}"
            context_blocks.append(block)
            citations.append(
                Citation(
                    id=index,
                    title=title,
                    url=url,
                    source="exa",
                )
            )
        if not context_blocks:
            context_blocks.append("Nem sikerült releváns találatot visszaadni a keresőből.")
        answer_text = self.answer_with_gpt_oss(
            query=request.query,
            context_blocks=context_blocks,
            maximum_tokens=request.maximum_tokens,
        )
        try:
            self.supermemory_client.add_document(
                content=answer_text,
                source="answer",
                document_type="search_answer",
                metadata={
                    "query": request.query,
                    "mode": request.mode,
                    "user_id": request.user_id or "",
                    "timestamp": time.time(),
                    "engine": "exa+cerebras",
                },
            )
        except HTTPException:
            pass
        debug: Dict[str, Any] = {
            "plan_steps": plan_steps,
            "raw_result_count": len(raw_results.get("results", [])),
            "filtered_result_count": len(filtered_results),
        }
        return QueryResponse(
            answer=answer_text,
            citations=citations,
            plan=plan_steps,
            debug=debug,
        )

    def handle_research(
        self,
        request: QueryRequest,
    ) -> QueryResponse:
        plan_steps = self.plan_with_qwen(request.query)
        research_output = self.parallel_client.deep_research_markdown(
            query=request.query,
            timeout_seconds=3600,
        )
        markdown_report = str(research_output.get("raw_output", ""))
        context_blocks = [markdown_report]
        answer_text = self.answer_with_zai_glm(
            query=request.query,
            context_blocks=context_blocks,
            maximum_tokens=request.maximum_tokens,
        )
        citations: List[Citation] = [
            Citation(
                id=1,
                title="Parallel Deep Research Task Output",
                url=None,
                source="parallel",
            )
        ]
        try:
            self.supermemory_client.add_document(
                content=markdown_report,
                source="parallel",
                document_type="parallel_research_raw",
                metadata={
                    "query": request.query,
                    "user_id": request.user_id or "",
                    "timestamp": time.time(),
                    "run_id": research_output.get("run_id", ""),
                },
            )
            self.supermemory_client.add_document(
                content=answer_text,
                source="answer",
                document_type="research_answer",
                metadata={
                    "query": request.query,
                    "mode": request.mode,
                    "user_id": request.user_id or "",
                    "timestamp": time.time(),
                    "engine": "parallel+cerebras",
                },
            )
        except HTTPException:
            pass
        debug: Dict[str, Any] = {
            "plan_steps": plan_steps,
            "parallel_run_id": research_output.get("run_id", ""),
        }
        return QueryResponse(
            answer=answer_text,
            citations=citations,
            plan=plan_steps,
            debug=debug,
        )


app = FastAPI(
    title="Deep Research Search Backend",
    version="1.0.0",
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

exa_client_instance = ExaClient()
parallel_client_instance = ParallelResearchClient()
supermemory_client_instance = SupermemoryClient()
orchestrator = CerebrasLLMOrchestrator(
    exa_client=exa_client_instance,
    parallel_client=parallel_client_instance,
    supermemory_client=supermemory_client_instance,
)


@app.post("/query", response_model=QueryResponse)
def query_endpoint(request: QueryRequest) -> QueryResponse:
    if request.mode == "search":
        return orchestrator.handle_search(request)
    if request.mode == "research":
        return orchestrator.handle_research(request)
    raise HTTPException(status_code=400, detail="Unsupported mode")


