    background-color: #111111;
    border: 1px solid #333333;
    overflow: hidden;
}
.mode-button {
    padding: 6px 12px;
    font-size: 12px;
    border: none;
    background: transparent;
    color: #bbbbbb;
    cursor: pointer;
    transition: background-color 0.12s ease-out, color 0.12s ease-out;
}
.mode-button.active {
    background-color: #f5f5f5;
    color: #000000;
}
#action-buttons {
    display: inline-flex;
    gap: 8px;
    flex-wrap: nowrap;
}
.action-button {
    border: none;
    border-radius: 999px;
    padding: 8px 16px;
    font-size: 13px;
    cursor: pointer;
    transition: background-color 0.12s ease-out, transform 0.06s ease-out;
    white-space: nowrap;
}
#search-button {
    background-color: #f5f5f5;
    color: #000000;
}
#search-button:active {
    transform: scale(0.97);
}
#stop-button {
    background-color: #222222;
    color: #f5f5f5;
    display: none;
}
#status-text {
    font-size: 11px;
    opacity: 0.7;
}
#status-dot {
    width: 6px;
    height: 6px;
    border-radius: 999px;
    background-color: #4f8cff;
    display: inline-block;
    margin-right: 4px;
}
#output-container {
    flex: 1 1 auto;
    margin-top: 8px;
    padding: 10px 12px 12px 12px;
    border-radius: 10px;
    background-color: #050505;
    border: 1px solid #222222;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
}
#answer {
    font-size: 14px;
    line-height: 1.5;
    white-space: pre-wrap;
}
#plan {
    font-size: 12px;
    opacity: 0.8;
    margin-bottom: 8px;
}
#citations {
    font-size: 11px;
    opacity: 0.8;
    margin-top: 10px;
}
#plan-title {
    font-weight: 600;
    margin-bottom: 2px;
}
#citations-title {
    font-weight: 600;
    margin-bottom: 2px;
}
.plan-item {
    margin-left: 10px;
}
.citation-item {
    margin-left: 10px;
}
@media (min-width: 768px) {
    header h1 {
        font-size: 20px;
    }
    #query-input {
        min-height: 96px;
    }
}
</style>
</head>
<body>
<div id="app">
<header>
    <div>
        <h1>AI Deep Search</h1>
        <span>Reasoning web assistant</span>
    </div>
    <div id="status-text">
        <span id="status-dot"></span><span id="status-label">Kész</span>
    </div>
</header>
<main>
    <div id="input-container">
        <textarea id="query-input" placeholder="Írd be a kérdésed vagy kutatási témád..."></textarea>
        <div id="controls-row">
            <div id="mode-toggle-group">
                <button id="mode-search" class="mode-button active" data-mode="search">Gyors keresés</button>
                <button id="mode-research" class="mode-button" data-mode="research">Mély kutatás</button>
            </div>
            <div id="action-buttons">
                <button id="search-button" class="action-button">Indítás</button>
                <button id="stop-button" class="action-button">Leállítás</button>
            </div>
        </div>
    </div>
    <div id="output-container">
        <div id="plan"></div>
        <div id="answer"></div>
        <div id="citations"></div>
    </div>
</main>
</div>
<script>
(function () {
    var backendUrl = (window.location.origin || "").replace(/\/+$/, "") + "/query";
    var queryInput = document.getElementById("query-input");
    var modeSearchButton = document.getElementById("mode-search");
    var modeResearchButton = document.getElementById("mode-research");
    var searchButton = document.getElementById("search-button");
    var stopButton = document.getElementById("stop-button");
    var statusDot = document.getElementById("status-dot");
    var statusLabel = document.getElementById("status-label");
    var planContainer = document.getElementById("plan");
    var answerContainer = document.getElementById("answer");
    var citationsContainer = document.getElementById("citations");
    var currentMode = "search";
    var currentAbortController = null;
    function setMode(mode) {
        currentMode = mode;
        if (mode === "search") {
            modeSearchButton.classList.add("active");
            modeResearchButton.classList.remove("active");
        } else {
            modeSearchButton.classList.remove("active");
            modeResearchButton.classList.add("active");
        }
    }
    function setBusy(isBusy, label) {
        if (isBusy) {
            statusDot.style.backgroundColor = "#ffc857";
            statusLabel.textContent = label || "Dolgozom…";
            searchButton.style.display = "none";
            stopButton.style.display = "inline-block";
        } else {
            statusDot.style.backgroundColor = "#4f8cff";
            statusLabel.textContent = "Kész";
            searchButton.style.display = "inline-block";
            stopButton.style.display = "none";
        }
    }
    function renderPlan(planSteps) {
        if (!planSteps || !planSteps.length) {
            planContainer.textContent = "";
            return;
        }
        var fragment = document.createDocumentFragment();
        var title = document.createElement("div");
        title.id = "plan-title";
        title.textContent = "Gondolkodási terv:";
        fragment.appendChild(title);
        for (var index = 0; index < planSteps.length; index += 1) {
            var item = document.createElement("div");
            item.className = "plan-item";
            item.textContent = (index + 1) + ". " + planSteps[index];
            fragment.appendChild(item);
        }
        planContainer.innerHTML = "";
        planContainer.appendChild(fragment);
    }
    function renderAnswer(text) {
        answerContainer.textContent = text || "";
    }
    function renderCitations(citations) {
        if (!citations || !citations.length) {
            citationsContainer.textContent = "";
            return;
        }
        var fragment = document.createDocumentFragment();
        var title = document.createElement("div");
        title.id = "citations-title";
        title.textContent = "Források:";
        fragment.appendChild(title);
        for (var index = 0; index < citations.length; index += 1) {
            var citation = citations[index];
            var item = document.createElement("div");
            item.className = "citation-item";
            var label = "[" + citation.id + "]";
            if (citation.title) {
                label += " " + citation.title;
            }
            if (citation.url) {
                var link = document.createElement("a");
                link.href = citation.url;
                link.textContent = label;
                link.target = "_blank";
                link.rel = "noopener noreferrer";
                link.style.color = "#7fb3ff";
                item.appendChild(link);
            } else {
                item.textContent = label;
            }
            fragment.appendChild(item);
        }
        citationsContainer.innerHTML = "";
        citationsContainer.appendChild(fragment);
    }
    function startQuery() {
        var queryText = queryInput.value.trim();
        if (!queryText) {
            return;
        }
        if (currentAbortController) {
            currentAbortController.abort();
        }
        currentAbortController = new AbortController();
        setBusy(true, currentMode === "search" ? "Gyors keresés…" : "Mély kutatás…");
        planContainer.textContent = "";
        answerContainer.textContent = "";
        citationsContainer.textContent = "";
        var payload = {
            query: queryText,
            mode: currentMode,
            maximum_tokens: 2048
        };
        fetch(backendUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(payload),
            signal: currentAbortController.signal
        }).then(function (response) {
            if (!response.ok) {
                throw new Error("HTTP " + response.status);
            }
            return response.json();
        }).then(function (data) {
            renderPlan(data.plan || []);
            renderAnswer(data.answer || "");
            renderCitations(data.citations || []);
        }).catch(function (error) {
            if (error.name === "AbortError") {
                renderAnswer("A kérés megszakadt.");
            } else {
                renderAnswer("Hiba történt a lekérdezés közben: " + error.message);
            }
        }).finally(function () {
            setBusy(false);
            currentAbortController = null;
        });
    }
    function stopQuery() {
        if (currentAbortController) {
            currentAbortController.abort();
            currentAbortController = null;
        }
        setBusy(false);
    }
    modeSearchButton.addEventListener("click", function () {
        setMode("search");
    });
    modeResearchButton.addEventListener("click", function () {
        setMode("research");
    });
    searchButton.addEventListener("click", function () {
        startQuery();
    });
    stopButton.addEventListener("click", function () {
        stopQuery();
    });
    queryInput.addEventListener("keydown", function (event) {
        if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            startQuery();
        }
    });
    if ("serviceWorker" in navigator) {
        window.addEventListener("load", function () {
            try {
                navigator.serviceWorker.register("/service-worker.js");
            } catch (error) {
            }
        });
    }
})();
</script>
</body>
</html>
